\label{thm:tpca}
 Let $\hat{\bm V}$ denote any estimator for $k$-TPCA with $k \geq 2$ and  $\lambda \asymp 1$ (as $\dim \rightarrow \infty$) that can be computed using a memory bounded estimation algorithm with resource profile $(\ssize, \iters, \state)$ scaling with $\dim$ as
 \begin{align*}
   \ssize \asymp \dim^{\eta}/\lambda^2, \quad \iters \asymp \dim^\tau, \quad \state \asymp \dim^{\mu}
 \end{align*}
 for any constants $\eta \geq 1, \; \tau \geq 0, \; \mu \geq 0$. If
 \begin{align*}
   \eta + \tau + \mu  < \left\lceil\frac{k+1}{2} \right\rceil,
 \end{align*}
 then, for any $t \in \R$,
 \begin{align*}
   \limsup_{\dim \rightarrow \infty} \inf_{\bm V \in \paramspace} \P_{\bm V}\left( \frac{|\langle{\bm V,}{\hat{\bm V}} \rangle|^2}{\|\bm V\|^2 \|\hat{\bm V}\|^2}  \geq \frac{t^2}{d} \right) & \leq 2\exp\left( - \frac{t^2}{2}\right).
 \end{align*}

\label{thm:main-result-atpca}
Let $\hat{\bm V} \in \tensor{\R^\dim}{k}$ denote any estimator for $k$-ATPCA with $k \geq 2$ and signal-to-noise ratio $\lambda \asymp 1$ (as $\dim \rightarrow \infty$) that can be computed using a memory bounded estimation algorithm with resource profile $(\ssize, \iters, \state)$ scaling with $\dim$ as
 \begin{align*}
     \ssize \asymp \dim^{\eta}/\lambda^2, \quad \iters \asymp\dim^\tau, \quad \state \asymp\dim^{b}
 \end{align*}
 for any constants $\eta > 0, \; \tau \geq 0, \; b \geq 0$. If
\begin{align*}
    \eta + \tau + b  < k,
\end{align*}
then, for any $t \in \R$,
\begin{align*}
    \limsup_{\dim \rightarrow \infty} \inf_{\bm V \in \paramspace} \P_{\bm V}\left( \frac{|\langle{\bm V,}{\hat{\bm V}} \rangle|^2}{\|\bm V\|^2 \|\hat{\bm V}\|^2}  \geq \frac{t^2}{d^k} \right) & \leq \frac{1}{t^2}.
\end{align*}

 \label{thm:ngca}
  Consider the $k$-NGCA problem with non-Gaussian distribution $\nongauss$ satisfying
 \begin{enumerate}
    \item the Moment Matching Assumption (Assumption~\ref{ass: moment-matching}) with parameter $k\geq 2$ and $k \asymp 1$;
    \item the Bounded Signal Strength Assumption (Assumption~\ref{ass: bounded-snr}) with parameters $(\lambda,K \asymp 1)$;
    \item the Locally Bounded Likelihood Ratio Assumption (Assumption~\ref{ass: locally-bounded-LLR}) with parameters $(\lambda, K \asymp 1, \kappa \asymp 1)$.
\end{enumerate}
{Suppose that $\lambda \asymp \dim^{-\gamma}$ (as $\dim \rightarrow \infty$) for any constant $\gamma > 2 \lceil (k+1)/2 \rceil + \kappa$.} Let $\hat{\bm V} \in \R^\dim$ denote any estimator for this $k$-NGCA problem that can be computed using a memory bounded estimation algorithm with resource profile $(\ssize, \iters, \state)$  scaling with $\dim$ as 
 \begin{align*}
      \ssize \lambda^2  \asymp \dim^{\eta}, \quad \iters  \asymp \dim^\tau, \quad \state \asymp \dim^{\mu}
 \end{align*}
 for any constants $\eta \geq 1, \; \tau \geq 0, \; \mu \geq 0$. If
\begin{align*}
    \eta + \tau + \mu  < \left\lceil\frac{k+1}{2} \right\rceil,
\end{align*}
then, for any $t \in \R$,
\begin{align*}
    \limsup_{\dim \rightarrow \infty} \inf_{\bm V \in \paramspace} \P_{\bm V}\left( \frac{|\langle{\bm V,}{\hat{\bm V}} \rangle|^2}{\|\bm V\|^2 \|\hat{\bm V}\|^2}  \geq \frac{t^2}{d} \right) & \leq 2\exp\left( - \frac{t^2}{2}\right).
\end{align*}

 \label{thm:cca} Consider the $k$-CCA problem for $k\geq 2$ with signal-to-noise ratio $\lambda^2 \asymp \dim^{-\gamma}$ (as $\dim \rightarrow \infty$) for any constant $\gamma > 3k/2$. Let $\hat{\bm V} \in \tensor{\R^\dim}{k}$ denote any estimator for this $k$-CCA problem that can be computed using a memory bounded estimation algorithm with resource profile $(\ssize, \iters, \state)$ scaling with $\dim$ as
 \begin{align*}
 \ssize \lambda^2  \asymp \dim^{\eta}, \quad \iters  \asymp \dim^\tau, \quad \state \asymp \dim^{\mu}
 \end{align*}
 for any constants $\eta \geq 1, \; \tau \geq 0, \; \mu \geq 0$.
 If
\begin{align*}
    \eta + \tau + \mu  < k,
\end{align*}
then, for any $t \in \R$,
\begin{align*}
    \limsup_{\dim \rightarrow \infty} \inf_{\bm V \in \paramspace} \P_{\bm V}\left( \frac{|\langle{\bm V,}{\hat{\bm V}} \rangle|^2}{\|\bm V\|^2 \|\hat{\bm V}\|^2}  \geq \frac{t^2}{d^k} \right) & \leq \frac{1}{t^2}.
\end{align*}
These results hold even when $\bm V$ and $\dmu{\bm V}$ are promised to satisfy~\eqref{eq:kCCA-coordprior} and~\eqref{eq:kCCA-likelihood}.
